SELECT TRIP_ID, VEHICLE_ID, ORIGIN_POI_ID, TRIP_START, STATUS,
       ORIGIN, DESTINATION, ROUTE_GEOG, DURATION_MINUTES, DISTANCE_KM, REGION
FROM SYNTHETIC_DATASETS.UNIFIED.FACT_TRIPS
WHERE VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_FOOD_DELIVERY.CONFIG LIMIT 1)
  AND REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_FOOD_DELIVERY.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.FOOD_DELIVERY.VW_POIS AS
SELECT LOCATION_ID, NAME, POINT_GEOM, LOCATION_TYPE, REGION
FROM SYNTHETIC_DATASETS.UNIFIED.DIM_POIS
WHERE REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_FOOD_DELIVERY.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.FOOD_DELIVERY.VW_CONFIG AS
SELECT * FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_FOOD_DELIVERY.CONFIG;

CREATE OR REPLACE VIEW FLEET_APP.FOOD_DELIVERY.VW_DELIVERIES AS
SELECT
    t.TRIP_ID          AS DELIVERY_ID,
    t.VEHICLE_ID       AS COURIER_ID,
    p.NAME             AS RESTAURANT_NAME,
    t.ORIGIN_POI_ID    AS RESTAURANT_ID,
    t.TRIP_START       AS ORDER_TIME,
    t.STATUS           AS ORDER_STATUS,
    t.ORIGIN           AS PICKUP_LOCATION,
    t.DESTINATION      AS DROPOFF_LOCATION,
    t.DESTINATION      AS CUSTOMER_LOCATION,
    t.ROUTE_GEOG       AS GEOMETRY,
    t.DURATION_MINUTES AS DELIVERY_TIME_MIN,
    t.DISTANCE_KM      AS DISTANCE_KM
FROM FLEET_APP.FOOD_DELIVERY.VW_TRIPS t
LEFT JOIN FLEET_APP.FOOD_DELIVERY.VW_POIS p ON t.ORIGIN_POI_ID = p.LOCATION_ID;

CREATE OR REPLACE VIEW FLEET_APP.FOOD_DELIVERY.VW_RESTAURANTS_ENRICHED AS
SELECT
    p.LOCATION_ID            AS RESTAURANT_ID,
    p.NAME                   AS RESTAURANT_NAME,
    ANY_VALUE(p.POINT_GEOM)  AS LOCATION,
    COUNT(t.TRIP_ID)         AS TOTAL_ORDERS,
    ROUND(AVG(t.DURATION_MINUTES), 1) AS AVG_DELIVERY_TIME_MIN,
    p.REGION
FROM FLEET_APP.FOOD_DELIVERY.VW_POIS p
LEFT JOIN FLEET_APP.FOOD_DELIVERY.VW_TRIPS t ON p.LOCATION_ID = t.ORIGIN_POI_ID
WHERE p.LOCATION_TYPE = 'RESTAURANT'
GROUP BY p.LOCATION_ID, p.NAME, p.REGION;

